import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    var d: Int64 = 2
    let q = 10 / d
    let m = 10 % d
    if q == 5 { io.println("div-ok") } else { io.println("div-bad") }
    if m == 0 { io.println("mod-ok") } else { io.println("mod-bad") }
    let neg = 0 - 7
    let mneg = neg % 2
    if mneg == 0 - 1 { io.println("modneg-ok") } else { io.println("modneg-bad") }
    let qneg = neg / 2
    if qneg == 0 - 3 { io.println("divneg-ok") } else { io.println("divneg-bad") }
    let c = 17 % 5
    if c == 2 { io.println("constmod-ok") } else { io.println("constmod-bad") }
    let e = 17 / 5
    if e == 3 { io.println("constdiv-ok") } else { io.println("constdiv-bad") }
    return Ok(())
}
